  "concept-2-smile-bridge-master.svg": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 620 150\" width=\"100%\" height=\"100%\" fill=\"none\">\n  <!-- FundMeOut Master Wordmark: Smile Uplift Bridge -->\n  <defs>\n    <linearGradient id=\"electricBlueGrad\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#0047FF\"/>\n      <stop offset=\"100%\" stop-color=\"#0066FF\"/>\n    </linearGradient>\n    <linearGradient id=\"limeCyanGrad\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#06FF2E\"/>\n      <stop offset=\"100%\" stop-color=\"#00F0FF\"/>\n    </linearGradient>\n  </defs>\n\n  <style>\n    .brand-wordmark {\n      font-family: 'Plus Jakarta Sans', 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;\n      font-weight: 800;\n    }\n  </style>\n\n  <g transform=\"translate(20, 24)\">\n    <!-- \"FundMe\" -->\n    <text x=\"0\" y=\"74\" class=\"brand-wordmark\" font-size=\"68\" fill=\"#0047FF\" letter-spacing=\"-1.2\">FundMe</text>\n\n    <!-- \"Out\" with elevated prominence -->\n    <text x=\"300\" y=\"74\" class=\"brand-wordmark\" font-size=\"68\" fill=\"#0047FF\" letter-spacing=\"-1.2\">Out</text>\n\n    <!-- The Uplift Smile Bridge: Starts under the O and swoops with an uplifting smile flick beneath the 'ut' -->\n    <!-- Mimicking the iconic uplifting motion: uplifting someone OUT of need with a joyful smile -->\n    <path d=\"M 326 88 C 362 118, 430 118, 466 84\" stroke=\"url(#limeCyanGrad)\" stroke-width=\"7\" stroke-linecap=\"round\" fill=\"none\"/>\n    \n    <!-- Joyful terminal dimples / gesture tips -->\n    <circle cx=\"326\" cy=\"88\" r=\"4.5\" fill=\"#06FF2E\"/>\n    \n    <!-- Uplift arrowhead/dimple flick at the end of the swoop (reminiscent of Amazon's smile flick, but fresh and uplifting) -->\n    <path d=\"M 458 76 C 466 79, 472 82, 476 86 C 472 91, 465 96, 458 98 C 462 92, 463 85, 458 76 Z\" fill=\"#00F0FF\"/>\n  </g>\n</svg>\n",
